@@ -0,0 +1,41 @@
+// API keys, role permissions and the audit log of data changes.
+import { AppError } from "../errors.js";
+
+const RANK = { viewer: 1, cook: 2, manager: 3 };
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+/** Looks up an API key by its bearer token, or throws AppError unauthorized. */
+export function authenticateKey(store, token) {
+  const apiKey = typeof token === "string" && token ? (store.data.apiKeys ?? []).find((k) => k.key === token) : null;
+  if (!apiKey) throw new AppError("unauthorized");
+  return apiKey;
+}
+
+/** Checks that `apiKey` has permission for `method` on `pattern`, or throws AppError forbidden. */
+export function authorizeRoute(store, apiKey, method, pattern) {
+  let needed = "manager";
+  if (method === "GET" && pattern !== "/audit") needed = "viewer";
+  else if (COOK_ROUTES.has(`${method} ${pattern}`)) needed = "cook";
+  if ((RANK[apiKey?.role] ?? 0) < RANK[needed]) throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { at, keyName, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = { at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])]
+    .map((entry, i) => ({ entry, i }))
+    .sort((a, b) => b.entry.at.localeCompare(a.entry.at) || b.i - a.i)
+    .map((x) => x.entry);
+}
